def calculate_L(u, v, w):
    numerator = u + v + w
    denominator = u * v * w
    try:
        L = numerator / denominator
        print(f"For ({u}, {v}, {w}): L = {numerator}/{denominator} = {L}")
        if L == int(L):
            print("L is an integer.")
        else:
            print("L is not an integer.")
    except ZeroDivisionError:
        print("Error: Denominator is zero.")

